// Self-rescheduling poll loop; interval from OPCUA_POLL_MS.
// Each cycle: clear the client's item list, queue the 13 NodeIds,
// then trigger a readmultiple.
const pollMs = Math.max(500, Number(env.get('OPCUA_POLL_MS') || 5000));
const prefix = env.get('OPCUA_NODE_PREFIX') || 'ns=1;s=FACIS.EnergyMeter.';
const METRICS = [
    'active_power_l1_w', 'active_power_l2_w', 'active_power_l3_w',
    'active_power_total_w',
    'voltage_l1_v', 'voltage_l2_v', 'voltage_l3_v',
    'current_l1_a', 'current_l2_a', 'current_l3_a',
    'power_factor', 'total_energy_kwh', 'frequency_hz'
];

const existing = context.get('poll_timer');
if (existing) clearTimeout(existing);

function firePoll() {
    const cycleId = context.get('cycle_seq') || 0;
    context.set('cycle_seq', cycleId + 1);
    node.send({ topic: 'clearitems' });
    for (const metric of METRICS) {
        node.send({ topic: prefix + metric });
    }
    node.send({
        topic: 'readmultiple',
        cycle_id: 'c' + cycleId,
        cycle_started_at: new Date().toISOString(),
        expected_items: METRICS.length
    });
    context.set('poll_timer', setTimeout(firePoll, pollMs));
}
firePoll();
return null;

// Collect per-item readmultiple outputs into one snapshot per cycle.
// Bad status or non-numeric value fails the whole cycle (no partials).
if (!msg.cycle_id || msg.topic === 'readmultiple' || msg.topic === 'clearitems') {
    return null;
}

const prefix = env.get('OPCUA_NODE_PREFIX') || 'ns=1;s=FACIS.EnergyMeter.';
const expected = Number(msg.expected_items || 13);

let cycles = context.get('cycles') || {};
const failed = context.get('failed_cycles') || {};
if (failed[msg.cycle_id]) return null;

const cycle = cycles[msg.cycle_id] || { items: [] };
const statusName = msg.statusCode && msg.statusCode.name ? String(msg.statusCode.name) : 'Good';
const metric = String(msg.topic).startsWith(prefix)
    ? String(msg.topic).slice(prefix.length)
    : String(msg.topic);

function failCycle(reason) {
    delete cycles[msg.cycle_id];
    failed[msg.cycle_id] = true;
    const keys = Object.keys(failed);
    if (keys.length > 20) delete failed[keys[0]];
    context.set('cycles', cycles);
    context.set('failed_cycles', failed);
    node.error('opcua-client: ' + reason, msg);
}

if (/^Bad/.test(statusName)) {
    failCycle('Bad status for ' + metric + ' (' + statusName + ')');
    return null;
}
const value = Number(msg.payload);
if (!Number.isFinite(value)) {
    failCycle('non-numeric value for ' + metric);
    return null;
}

cycle.items.push({
    metric: metric,
    value: value,
    status: statusName,
    source_timestamp: msg.sourceTimestamp || null
});

if (cycle.items.length < expected) {
    cycles[msg.cycle_id] = cycle;
    // Drop stale cycles so an interrupted read cannot leak memory.
    const ids = Object.keys(cycles);
    if (ids.length > 5) delete cycles[ids[0]];
    context.set('cycles', cycles);
    return null;
}

delete cycles[msg.cycle_id];
context.set('cycles', cycles);

const readings = {};
let quality = 'good';
let sourceTimestamp = null;
for (const item of cycle.items) {
    readings[item.metric] = item.value;
    if (/^Uncertain/.test(item.status)) quality = 'uncertain';
    if (!sourceTimestamp && item.source_timestamp) sourceTimestamp = item.source_timestamp;
}

msg.readings = readings;
msg.quality = quality;
msg.source_timestamp = sourceTimestamp
    ? new Date(sourceTimestamp).toISOString()
    : msg.cycle_started_at;
msg.raw_items = cycle.items;
return msg;

// Build the industrial ingestion envelope and the Kafka producer msg.
const endpoint = env.get('OPCUA_ENDPOINT') || 'opc.tcp://127.0.0.1:4840';
const siteId = env.get('INDING_SITE_ID') || 'site-001';
const deviceId = env.get('OPCUA_DEVICE_ID') || 'janitza-umg96rm-001';
const sourceTimestamp = msg.source_timestamp || new Date().toISOString();

const envelope = {
    schema_version: '1.0',
    event_id: endpoint + '|' + deviceId + '|' + sourceTimestamp,
    ingest_timestamp: new Date().toISOString(),
    source_protocol: 'opc-ua',
    source_endpoint: endpoint,
    site_id: siteId,
    device_id: deviceId,
    source_timestamp: sourceTimestamp,
    quality: msg.quality || 'good',
    readings: msg.readings,
    raw_payload: JSON.stringify(msg.raw_items)
};

const m = global.get('metrics') || {};
m.facis_inding_opcua_published_total = (m.facis_inding_opcua_published_total || 0) + 1;
global.set('metrics', m);

return {
    topic: env.get('OPCUA_INGEST_TOPIC') || 'opcua.ingest.raw',
    key: deviceId,
    payload: JSON.stringify(envelope),
    _inding_envelope: envelope,
    _inding_device: deviceId,
    _inding_protocol: 'opc-ua'
};

// Route any error on this tab to the shared DLQ with a typed envelope.
let errorType = 'read';
if (msg && msg._inding_envelope) errorType = 'publish';
else if (msg && msg.readings) errorType = 'validate';

return {
    payload: {
        error_type: errorType,
        error_message: msg && msg.error ? (msg.error.message || String(msg.error)) : 'unknown error',
        error_timestamp: new Date().toISOString(),
        source_protocol: 'opc-ua',
        device_id: (msg && msg._inding_device) || env.get('OPCUA_DEVICE_ID') || null,
        original_envelope: (msg && msg._inding_envelope) || null
    }
};
